<template>
  <div class="agent-page">
    <header class="agent-heading">
      <div><span class="eyebrow">GOAL-DRIVEN WORKSPACE</span><h1>Agent Workspace</h1><p>查看 Agent 如何使用上下文与只读工具完成目标。</p></div>
      <div class="heading-actions">
        <el-button class="mobile-runs" @click="runsDrawerOpen=true">最近执行</el-button>
        <el-button class="new-goal" type="primary" @click="openComposer">＋ 新建目标</el-button>
      </div>
    </header>

    <main v-if="agentStore.listLoading && agentStore.runs.length===0" class="page-state" v-loading="true" aria-live="polite"><p>正在加载 Agent Runs…</p></main>
    <main v-else-if="agentStore.listError && agentStore.runs.length===0" class="page-state page-state--error" role="alert"><span class="state-mark">!</span><h2>无法加载 Agent Workspace</h2><p>{{ agentStore.listError }}</p><el-button @click="loadRuns">重试</el-button></main>
    <main v-else-if="agentStore.runs.length===0" class="page-state page-state--empty">
      <span class="state-mark" aria-hidden="true">✦</span><h2>{{ AGENT_EMPTY_STATE.title }}</h2><p>{{ AGENT_EMPTY_STATE.description }}</p><el-button type="primary" @click="openComposer">＋ 新建目标</el-button>
    </main>

    <main v-else class="workspace-grid">
      <aside class="runs-panel" aria-label="最近 Agent Runs"><AgentRunList :runs="agentStore.runs" :selected-run-id="agentStore.selectedRunId" :loading="agentStore.listLoading" :error="agentStore.listError" @select="chooseRun" @retry="loadRuns" /></aside>
      <section class="workspace-panel" aria-label="Run Workspace" :aria-busy="agentStore.detailLoading">
        <div v-if="agentStore.detailError" class="detail-error" role="alert"><h2>无法加载 Run</h2><p>{{ agentStore.detailError }}</p><el-button v-if="agentStore.selectedRunId" @click="retryDetail">重试</el-button></div>
        <div v-else-if="agentStore.detailLoading && !visibleRun" class="workspace-placeholder" v-loading="true"><p>正在加载 Run 详情…</p></div>
        <div v-else-if="visibleRun" class="run-overview">
          <div v-if="agentStore.pollingWarning" class="polling-warning" role="status"><span>连接暂时异常</span><p>{{ agentStore.pollingWarning }} 已保留最近一次成功状态。</p></div>
          <header class="run-header"><div><span class="eyebrow">RUN #{{ visibleRun.id }}</span><h2>{{ summarizeAgentGoal(visibleRun.goal,120) }}</h2></div><div class="run-state-actions"><span class="run-status" :data-tone="statusView.tone">{{ statusView.label }}</span><el-button v-if="resumeVisible" type="primary" :loading="agentStore.resumeLoading" :disabled="agentStore.resumeLoading" :aria-label="resumeLabel" @click="resumeSelectedRun">{{ resumeLabel }}</el-button></div></header>
          <section class="recovery-card" :data-tone="recoveryView.tone" role="status"><strong>{{ recoveryView.label }}</strong><p>{{ recoveryView.description }}</p></section>
          <section v-if="agentStore.resumeError" class="resume-error" role="alert"><strong>Resume request failed</strong><p>{{ agentStore.resumeError }}</p><el-button v-if="resumeVisible" :loading="agentStore.resumeLoading" @click="resumeSelectedRun">Retry Resume</el-button></section>
          <section class="goal-card"><span>目标</span><p>{{ visibleRun.goal }}</p></section>
          <dl class="run-facts"><div><dt>执行进度</dt><dd>{{ visibleRun.currentStep }} / {{ visibleRun.maxSteps }}</dd></div><div><dt>恢复状态</dt><dd>{{ agentRecoveryLabel(visibleRun.recoveryState) }}</dd></div><div><dt>创建时间</dt><dd>{{ formatAgentTime(visibleRun.createTime) }}</dd></div><div><dt>更新时间</dt><dd>{{ formatAgentTime(visibleRun.updateTime) }}</dd></div><div><dt>完成时间</dt><dd>{{ formatAgentTime(visibleRun.completionTime) }}</dd></div><div><dt>可恢复</dt><dd>{{ visibleRun.canResume ? '是' : '否' }}</dd></div></dl>
          <section v-if="visibleRun.status==='FAILED'" class="result-card result-card--error" aria-labelledby="run-failure-title"><span>FAILED</span><h3 id="run-failure-title">Agent Run Failed</h3><strong>{{ visibleRun.lastErrorCode || 'AGENT_ERROR' }}</strong><p>{{ visibleRun.lastErrorMessage || '执行未能完成。' }}</p><small>Updated {{ formatAgentTime(visibleRun.updateTime) }} · Completed {{ formatAgentTime(visibleRun.completionTime) }}</small><el-button v-if="failedStep" @click="viewFailedStep">View failed step</el-button></section>
          <section v-else-if="visibleRun.status==='COMPLETED'" class="result-card final-result" aria-labelledby="final-result-title"><span class="completed-badge">COMPLETED</span><h3 id="final-result-title">Final Result</h3><AgentPayloadBlock title="Final Result" :payload="finalPayload" /><small>Completed {{ formatAgentTime(visibleRun.completionTime) }}</small></section>
          <AgentStepTimeline :steps="visibleRun.steps" :selected-step-id="selectedStepId" @select="selectStep" />
          <el-button v-if="selectedStep" class="mobile-detail" @click="detailDrawerOpen=true">查看 Step Detail</el-button>
        </div>
        <div v-else class="workspace-placeholder"><span class="state-mark" aria-hidden="true">↖</span><h2>选择一个 Run</h2><p>从最近执行中选择一项，查看目标与当前状态。</p></div>
      </section>
      <aside class="detail-panel" aria-label="Step Detail"><AgentStepDetail :step="selectedStep" :run-final-result="visibleRun?.finalResult||''" /></aside>
    </main>

    <el-drawer v-model="runsDrawerOpen" class="agent-v2-drawer" title="最近执行" direction="ltr" size="min(88vw, 340px)"><AgentRunList :runs="agentStore.runs" :selected-run-id="agentStore.selectedRunId" :loading="agentStore.listLoading" :error="agentStore.listError" @select="chooseRun" @retry="loadRuns" /></el-drawer>
    <el-drawer v-model="detailDrawerOpen" class="agent-v2-drawer" title="Step Detail" direction="rtl" size="min(92vw, 420px)"><AgentStepDetail :step="selectedStep" :run-final-result="visibleRun?.finalResult||''" /></el-drawer>
    <el-dialog v-model="composerOpen" title="新建 Agent Goal" width="min(92vw, 620px)" :close-on-click-modal="!agentStore.createLoading" :close-on-press-escape="!agentStore.createLoading">
      <div class="goal-composer"><label for="agent-goal">Goal</label><el-input id="agent-goal" v-model="goalDraft" type="textarea" :rows="7" maxlength="4000" show-word-limit resize="vertical" placeholder="描述你希望 Agent 完成的目标" :disabled="agentStore.createLoading" @keydown.ctrl.enter.prevent="submitGoal" /><p class="composer-help">Agent 将根据目标自主选择可用的只读上下文工具。</p><div v-if="agentStore.createError" class="composer-error" role="alert"><strong>创建请求未确认</strong><p>{{ agentStore.createError }}</p><small>重试会复用同一个 requestId，避免创建重复 Run。</small></div></div>
      <template #footer><div class="composer-actions"><el-button :disabled="agentStore.createLoading" @click="composerOpen=false">取消</el-button><el-button v-if="agentStore.createError&&agentStore.pendingRequestId" type="primary" :loading="agentStore.createLoading" @click="retryGoal">重试同一请求</el-button><el-button v-else type="primary" :loading="agentStore.createLoading" :disabled="agentStore.createLoading" @click="submitGoal">创建 Run</el-button></div></template>
    </el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'
import AgentRunList from '../components/agent/AgentRunList.vue'
import AgentStepTimeline from '../components/agent/AgentStepTimeline.vue'
import AgentStepDetail from '../components/agent/AgentStepDetail.vue'
import AgentPayloadBlock from '../components/agent/AgentPayloadBlock.vue'
import { useAgentStore } from '../stores/agent'
import { AGENT_EMPTY_STATE, agentRecoveryLabel, agentStatusPresentation, canShowResume, chooseDefaultStep, finalResultPresentation, findFailedStep, formatAgentTime, getResumeLabel, getRunRecoveryPresentation, parseAgentRunId, shouldFollowLatestStep, summarizeAgentGoal } from '../utils/agentPresentation'

const route=useRoute(),router=useRouter(),agentStore=useAgentStore()
const runsDrawerOpen=ref(false),detailDrawerOpen=ref(false),composerOpen=ref(false),goalDraft=ref(''),selectedStepId=ref(null),followLatestStep=ref(true)
const visibleRun=computed(()=>agentStore.selectedRun?.id===agentStore.selectedRunId?agentStore.selectedRun:null)
const selectedStep=computed(()=>visibleRun.value?.steps.find(step=>step.id===selectedStepId.value)||null)
const statusView=computed(()=>agentStatusPresentation(visibleRun.value?.status))
const recoveryView=computed(()=>getRunRecoveryPresentation(visibleRun.value))
const resumeVisible=computed(()=>canShowResume(visibleRun.value))
const resumeLabel=computed(()=>getResumeLabel(visibleRun.value))
const failedStep=computed(()=>findFailedStep(visibleRun.value?.steps))
const finalPayload=computed(()=>finalResultPresentation(visibleRun.value?.finalResult))
const loadRuns=()=>agentStore.loadRuns().catch(()=>{})
const retryDetail=()=>agentStore.loadRun().catch(()=>{})
const chooseRun=async id=>{runsDrawerOpen.value=false;if(parseAgentRunId(route.query.runId)===id){await agentStore.selectRun(id).catch(()=>{});return}await router.replace({query:{...route.query,runId:String(id)}})}
const openComposer=()=>{agentStore.createError='';agentStore.pendingGoal='';agentStore.pendingRequestId='';goalDraft.value='';composerOpen.value=true}
const finishCreate=async run=>{if(!run)return;goalDraft.value='';composerOpen.value=false;await router.replace({query:{...route.query,runId:String(run.id)}})}
const submitGoal=async()=>{try{await finishCreate(await agentStore.createRun(goalDraft.value))}catch{}}
const retryGoal=async()=>{try{await finishCreate(await agentStore.retryCreate())}catch{}}
const selectStep=id=>{selectedStepId.value=id;followLatestStep.value=shouldFollowLatestStep(id,visibleRun.value?.steps||[]);if(typeof window!=='undefined'&&window.matchMedia?.('(max-width: 760px)').matches)detailDrawerOpen.value=true}
const resumeSelectedRun=async()=>{const id=visibleRun.value?.id;if(!id||id!==agentStore.selectedRunId||!canShowResume(visibleRun.value))return;await agentStore.resumeRun(id).catch(()=>{})}
const viewFailedStep=()=>{if(failedStep.value)selectStep(failedStep.value.id)}

watch(()=>agentStore.selectedRunId,()=>{selectedStepId.value=null;followLatestStep.value=true})
watch(()=>visibleRun.value?.steps||[],(steps,previousSteps)=>{
  if(steps.length===0){selectedStepId.value=null;followLatestStep.value=true;return}
  const stillExists=steps.some(step=>step.id===selectedStepId.value)
  const wasFollowing=followLatestStep.value||(!stillExists&&shouldFollowLatestStep(selectedStepId.value,previousSteps||[]))
  if(!stillExists||wasFollowing){selectedStepId.value=chooseDefaultStep(steps)?.id??null;followLatestStep.value=true}
})

const syncRouteRun=async value=>{
  if(value==null||value===''){if(agentStore.selectedRunId) await agentStore.selectRun(agentStore.selectedRunId).catch(()=>{});return}
  const id=parseAgentRunId(value)
  if(id&&agentStore.selectedRunId===id&&agentStore.selectedRun?.id===id){agentStore.startPolling(id);return}
  await agentStore.selectRun(value).catch(()=>{})
}
watch(()=>route.query.runId,syncRouteRun)
onMounted(async()=>{agentStore.attachVisibility();await loadRuns();await syncRouteRun(route.query.runId)})
onUnmounted(()=>agentStore.disposePolling())
onBeforeRouteLeave(()=>agentStore.disposePolling())
</script>

