.polling-warning{margin-bottom:18px;padding:12px 14px;border:1px solid #efd49e;border-radius:var(--app-radius-sm);color:var(--app-warning);background:var(--app-warning-soft)}.polling-warning span{font-weight:800}.polling-warning p{margin-top:3px}.progress-list{margin-top:16px;padding:18px;border:1px solid var(--app-border);border-radius:var(--app-radius-md);background:var(--app-surface)}.progress-list>header{display:flex;justify-content:space-between}.progress-list>header p{color:var(--app-text-muted)}.progress-list ol{display:grid;gap:8px;margin-top:14px}.progress-list li{min-width:0;display:grid;grid-template-columns:28px minmax(0,1fr) auto;align-items:center;gap:10px;padding:10px;border-radius:var(--app-radius-sm);background:var(--app-surface-subtle)}.progress-list li p{overflow:hidden;margin-top:2px;color:var(--app-text-secondary);text-overflow:ellipsis;white-space:nowrap}.progress-list li>span:last-child{color:var(--app-text-muted);font-size:10px;font-weight:750}.step-number{width:26px;height:26px;display:grid;place-items:center;border-radius:50%;color:var(--app-primary-strong);font-weight:800;background:var(--app-primary-soft)}
.workspace-placeholder,.detail-placeholder,.page-state{min-height:420px;display:grid;place-content:center;justify-items:center;gap:10px;text-align:center}.detail-placeholder{min-height:100%}.detail-symbol,.state-mark{width:54px;height:54px;display:grid;place-items:center;border-radius:50%;color:var(--app-primary-strong);font-size:24px;background:var(--app-primary-soft)}.detail-placeholder small{max-width:240px}.detail-error{padding:24px;border-radius:var(--app-radius-md);color:var(--app-danger);background:var(--app-danger-soft)}.detail-error p{margin:8px 0 14px}.page-state{width:min(720px,100%);min-height:460px;margin:30px auto;padding:40px;border:1px solid var(--app-border);border-radius:var(--app-radius-lg);background:rgba(255,255,255,.9);box-shadow:var(--app-shadow-lg)}.page-state p{max-width:520px;color:var(--app-text-secondary);line-height:1.6}.page-state--error .state-mark{color:var(--app-danger);background:var(--app-danger-soft)}
.goal-composer label{display:block;margin-bottom:8px;color:var(--app-text);font-weight:800}.composer-help{margin-top:9px;color:var(--app-text-secondary)}.composer-error{margin-top:16px;padding:14px;border-radius:var(--app-radius-sm);color:var(--app-danger);background:var(--app-danger-soft)}.composer-error p{margin:5px 0}.composer-actions{display:flex;justify-content:flex-end;gap:10px}.composer-actions :deep(.el-button)+.composer-actions :deep(.el-button){margin-left:0}
.run-state-actions{display:flex;align-items:center;justify-content:flex-end;flex-wrap:wrap;gap:9px}.recovery-card,.resume-error{margin-top:16px;padding:16px 18px;border:1px solid var(--app-border);border-radius:var(--app-radius-md);background:var(--app-surface)}.recovery-card strong{display:block;margin-bottom:4px}.recovery-card p,.resume-error p{line-height:1.6;color:var(--app-text-secondary);white-space:pre-wrap}.recovery-card[data-tone="recoverable"]{border-color:#efd49e;background:var(--app-warning-soft)}.recovery-card[data-tone="running"]{border-color:#c9dff6;background:var(--app-primary-soft)}.resume-error{color:var(--app-danger);background:var(--app-danger-soft)}.resume-error p{margin:5px 0 10px}.final-result{display:grid;gap:10px}.final-result h3,.result-card--error h3{font-size:20px}.final-result small,.result-card--error small{color:var(--app-text-muted)}.completed-badge{width:max-content!important;margin:0!important;padding:4px 8px;border-radius:var(--app-radius-pill);color:var(--app-success)!important;background:var(--app-success-soft)}.result-card--error .el-button{width:max-content;margin-top:12px}
@media(max-width:1120px){.mobile-runs{display:inline-flex}.workspace-grid{grid-template-columns:minmax(0,1fr) 320px}.runs-panel{display:none}}
@media(max-width:760px){.agent-page{min-height:calc(100dvh - 112px);padding:28px 16px 40px}.agent-heading{align-items:flex-start;flex-direction:column}.agent-heading h1{font-size:31px}.heading-actions{width:100%;flex-wrap:wrap}.workspace-grid{min-height:520px;grid-template-columns:1fr}.workspace-panel{padding:20px}.detail-panel{display:none}.run-facts{grid-template-columns:repeat(2,minmax(0,1fr))}.run-header,.timeline-placeholder{align-items:flex-start;flex-direction:column}.mobile-detail{display:inline-flex;margin-top:18px}.page-state{min-height:390px;margin:0}.agent-heading :deep(.el-button)+.agent-heading :deep(.el-button){margin-left:0}}
