/* AIworld V2 prototype: scoped to the Agent workspace. Atmosphere stays soft; information stays sharp. */
.agent-page{--agent-bg:#111323;--agent-surface:rgba(24,28,48,.78);--agent-surface-strong:rgba(18,22,39,.94);--agent-surface-soft:rgba(42,47,72,.58);--agent-text:#f7f5ff;--agent-text-secondary:#cfcee0;--agent-text-muted:#9899b0;--agent-border:rgba(225,222,255,.16);--agent-border-strong:rgba(235,232,255,.28);--agent-glow-violet:rgba(149,117,255,.28);--agent-glow-cyan:rgba(90,220,225,.2);--agent-glow-rose:rgba(244,139,181,.18);--agent-glow-lime:rgba(199,224,142,.14);--agent-success:#a8dfc5;--agent-warning:#f1d5a5;--agent-danger:#f0aaa9;--agent-radius-sm:13px;--agent-radius-md:20px;--agent-radius-lg:28px;--agent-shadow:0 28px 70px rgba(3,5,18,.34),inset 0 1px 0 rgba(255,255,255,.08);--agent-blur:20px;--app-text:var(--agent-text);--app-text-secondary:var(--agent-text-secondary);--app-text-muted:var(--agent-text-muted);--app-border:var(--agent-border);--app-border-strong:var(--agent-border-strong);--app-surface:var(--agent-surface-strong);--app-surface-subtle:var(--agent-surface-soft);--app-bg-cool:rgba(17,20,36,.88);--app-primary:#b8a5ff;--app-primary-strong:#d8ceff;--app-primary-soft:rgba(157,128,255,.16);--app-success:var(--agent-success);--app-success-soft:rgba(104,190,151,.14);--app-warning:var(--agent-warning);--app-warning-soft:rgba(225,179,101,.14);--app-danger:var(--agent-danger);--app-danger-soft:rgba(218,102,109,.14);--app-radius-sm:var(--agent-radius-sm);--app-radius-md:var(--agent-radius-md);--app-radius-lg:var(--agent-radius-lg);position:relative;isolation:isolate;overflow:hidden;margin:-1px 0 0;background:var(--agent-bg)}
.agent-page::before{content:'';position:absolute;z-index:-2;inset:-18%;background:radial-gradient(circle at 16% 18%,var(--agent-glow-violet),transparent 30%),radial-gradient(circle at 84% 12%,var(--agent-glow-cyan),transparent 27%),radial-gradient(circle at 66% 74%,var(--agent-glow-rose),transparent 31%),radial-gradient(circle at 12% 86%,var(--agent-glow-lime),transparent 25%),radial-gradient(circle at 48% 46%,rgba(88,76,156,.15),transparent 36%);filter:saturate(.9);animation:agent-aura-drift 24s ease-in-out infinite alternate;transform-origin:center}
.agent-page::after{content:'';position:absolute;z-index:-1;inset:0;pointer-events:none;opacity:.055;background-image:repeating-radial-gradient(circle at 30% 20%,rgba(255,255,255,.8) 0 .55px,transparent .7px 3px);background-size:5px 5px;mix-blend-mode:soft-light}
.agent-heading,.workspace-grid,.page-state{position:relative;z-index:1}.agent-heading h1{font-weight:650;letter-spacing:-.045em;text-shadow:0 0 34px rgba(194,179,255,.2)}.agent-heading p{color:var(--agent-text-secondary)}.new-goal{box-shadow:0 8px 28px rgba(135,110,239,.22)}
.workspace-panel,.detail-panel,.page-state{border-color:var(--agent-border);background:linear-gradient(145deg,rgba(40,44,68,.72),rgba(19,23,41,.72));box-shadow:var(--agent-shadow);backdrop-filter:blur(var(--agent-blur)) saturate(1.08);-webkit-backdrop-filter:blur(var(--agent-blur)) saturate(1.08)}.workspace-panel{position:relative}.workspace-panel::before{content:'';position:absolute;inset:0 10% auto;height:1px;background:linear-gradient(90deg,transparent,rgba(255,255,255,.3),transparent)}
